/* @autogenerated */
import { computed, inject, Injectable } from '@angular/core';
import { APP_CONFIG } from './app-config.service';
import { I18nConfig, TenantConfig } from './app-config.model';

// Los únicos valores fijos: se usan solo si la configuración no trae `i18n.default-lang` / `tenant.default`
const FALLBACK_LANGUAGE = 'en';
const FALLBACK_TENANT = 'main';

export function defaultLanguage(i18n: I18nConfig | undefined): string {
  return i18n?.['default-lang'] ?? FALLBACK_LANGUAGE;
}

/** Idiomas disponibles; el idioma por defecto siempre está incluido. */
export function availableLanguages(i18n: I18nConfig | undefined): string[] {
  const langs = [...(i18n?.['available-langs'] ?? [FALLBACK_LANGUAGE])];
  const base = defaultLanguage(i18n);
  return langs.includes(base) ? langs : [...langs, base];
}

export function defaultTenant(tenant: TenantConfig | undefined): string {
  return tenant?.default ?? FALLBACK_TENANT;
}

/** Idioma y tenant por defecto, leídos de `i18n.default-lang` y `tenant.default`. */
@Injectable({ providedIn: 'root' })
export class DefaultsService {
  private readonly config = inject(APP_CONFIG);

  readonly language = computed(() => defaultLanguage(this.config().i18n));
  readonly tenant = computed(() => defaultTenant(this.config().tenant));
  readonly availableLanguages = computed(() => availableLanguages(this.config().i18n));
}
